/// Turns an HCI snoop log into a capture session.
///
/// This is the bridge between what the phone's Bluetooth stack recorded and
/// the evidence model the rest of the app reasons about. Every packet it
/// produces is marked as coming from an import, so that traffic generated by
/// the official Oraimo Health app is never mistaken for traffic we generated
/// ourselves.
library;

import 'dart:typed_data';

import '../../../core/hex/hex_codec.dart';
import '../../../core/models/ble_packet.dart';
import '../../../core/models/capture_session.dart';
import 'btsnoop_reader.dart';
import 'hci_parser.dart';

/// What an import produced, including what it could not resolve.
class BtsnoopImportResult {
  const BtsnoopImportResult({
    required this.session,
    required this.packets,
    required this.summary,
    required this.resolvedCharacteristics,
    required this.unresolvedHandles,
  });

  final CaptureSession session;
  final List<BlePacket> packets;
  final HciParseSummary summary;

  /// Handles this capture identified, and what it identified them as.
  final Map<int, String> resolvedCharacteristics;

  /// Handles seen in traffic that the capture never identified. Reported
  /// prominently: a capture that missed service discovery yields packets whose
  /// characteristic is genuinely unknown, and pretending otherwise would
  /// poison later analysis.
  final Set<int> unresolvedHandles;

  bool get hasUnresolvedHandles => unresolvedHandles.isNotEmpty;

  bool get hasTruncatedRecords => summary.truncatedRecords > 0;
}

/// A peer found in a capture, offered to the operator to choose from.
class BtsnoopPeer {
  const BtsnoopPeer({
    required this.address,
    required this.connectionHandles,
    required this.attPacketCount,
    required this.firstSeen,
    required this.lastSeen,
  });

  final String address;
  final List<int> connectionHandles;
  final int attPacketCount;
  final DateTime firstSeen;
  final DateTime? lastSeen;
}

/// What a capture contains, before committing to importing any of it.
class BtsnoopPreview {
  const BtsnoopPreview({
    required this.summary,
    required this.peers,
  });

  final HciParseSummary summary;
  final List<BtsnoopPeer> peers;
}

class BtsnoopImporter {
  /// Parses [bytes] without building any packets, so the operator can see what
  /// is in the file and pick the device before importing.
  ///
  /// A phone's snoop log contains traffic from every Bluetooth device it was
  /// talking to — headphones, a car, a keyboard. Importing all of it would
  /// bury the watch's traffic in noise.
  BtsnoopPreview preview(Uint8List bytes) {
    final parser = _parseAll(bytes).parser;
    return BtsnoopPreview(
      summary: parser.summary,
      peers: _peersFrom(parser),
    );
  }

  /// Imports the traffic for one peer address into a session.
  ///
  /// [peerAddress] null imports everything, which is occasionally what you
  /// want but usually is not.
  BtsnoopImportResult import({
    required Uint8List bytes,
    required String sessionId,
    required String sessionName,
    String? peerAddress,
    String? deviceName,
    String? sourceFileName,
    String? notes,
  }) {
    final parsed = _parseAll(bytes);
    final parser = parsed.parser;

    final wantedHandles = peerAddress == null
        ? null
        : parser.connections
            .where((c) => c.peerAddress == peerAddress)
            .map((c) => c.handle)
            .toSet();

    final packets = <BlePacket>[];
    final resolved = <int, String>{};
    final unresolved = <int>{};
    DateTime? sessionStart;
    var seq = 0;

    for (final att in parsed.packets) {
      if (wantedHandles != null && !wantedHandles.contains(att.connectionHandle)) {
        continue;
      }
      // Discovery traffic is what makes handles resolvable; it is recorded so
      // the evidence for each resolution stays in the session, rather than
      // being silently consumed by the parser.
      sessionStart ??= att.timestamp;

      final map = parser.attributeMapFor(att.connectionHandle);
      final handle = att.attributeHandle;
      final characteristicUuid =
          handle == null ? null : map.characteristicFor(handle);
      final descriptorUuid = handle == null ? null : map.descriptorFor(handle);
      final serviceUuid = handle == null ? null : map.serviceFor(handle);

      if (handle != null) {
        if (characteristicUuid != null) {
          resolved[handle] = characteristicUuid;
        } else if (descriptorUuid == null) {
          unresolved.add(handle);
        }
      }

      packets.add(BlePacket(
        sessionId: sessionId,
        seq: seq++,
        timestamp: att.timestamp,
        elapsedUs: att.timestamp.difference(sessionStart).inMicroseconds,
        direction: att.fromRemote
            ? PacketDirection.watchToPhone
            : PacketDirection.phoneToWatch,
        operation: _operationFor(att, descriptorUuid),
        payloadHex: bytesToHex(att.payload),
        serviceUuid: serviceUuid,
        characteristicUuid: characteristicUuid,
        descriptorUuid: descriptorUuid,
        attHandle: handle,
        status: att.operation == AttOperation.errorResponse
            ? PacketStatus.failed
            : PacketStatus.ok,
        error: att.operation == AttOperation.errorResponse
            ? _describeAttError(att.payload)
            : null,
        // Truncation is recorded on the packet itself, so a payload that is
        // missing bytes cannot be mistaken for a complete one later.
        note: att.truncated
            ? 'capture truncated this packet; payload is incomplete'
            : null,
      ));
    }

    final connections = parser.connections
        .where((c) => peerAddress == null || c.peerAddress == peerAddress)
        .toList();

    final session = CaptureSession(
      id: sessionId,
      name: sessionName,
      source: CaptureSource.btsnoopImport,
      startedAt: sessionStart ?? parser.summary.firstTimestamp ?? DateTime.now().toUtc(),
      endedAt: packets.isEmpty ? null : packets.last.timestamp,
      deviceAddress: peerAddress ??
          (connections.isNotEmpty ? connections.first.peerAddress : null),
      deviceName: deviceName,
      notes: notes,
      sourceFileName: sourceFileName,
      packetCount: packets.length,
    );

    return BtsnoopImportResult(
      session: session,
      packets: packets,
      summary: parser.summary,
      resolvedCharacteristics: resolved,
      unresolvedHandles: unresolved,
    );
  }

  ({HciParser parser, List<AttPacket> packets}) _parseAll(Uint8List bytes) {
    final reader = BtsnoopReader(bytes);
    final parser = HciParser();
    final packets = <AttPacket>[];

    for (final record in reader.records()) {
      packets.addAll(parser.addPacket(
        data: record.data,
        timestamp: record.timestamp,
        isReceived: record.isReceived,
        cumulativeDrops: record.cumulativeDrops,
        truncated: record.isTruncated,
      ));
    }
    return (parser: parser, packets: packets);
  }

  List<BtsnoopPeer> _peersFrom(HciParser parser) {
    final byAddress = <String, List<HciConnection>>{};
    for (final connection in parser.connections) {
      byAddress.putIfAbsent(connection.peerAddress, () => []).add(connection);
    }
    final peers = byAddress.entries.map((entry) {
      final connections = entry.value;
      return BtsnoopPeer(
        address: entry.key,
        connectionHandles: connections.map((c) => c.handle).toList(),
        attPacketCount:
            connections.fold(0, (sum, c) => sum + c.attPacketCount),
        firstSeen: connections
            .map((c) => c.openedAt)
            .reduce((a, b) => a.isBefore(b) ? a : b),
        lastSeen: connections
            .map((c) => c.closedAt)
            .whereType<DateTime>()
            .fold<DateTime?>(null, (a, b) => a == null || b.isAfter(a) ? b : a),
      );
    }).toList();
    // Busiest first: the watch doing a watch-face transfer will dominate.
    peers.sort((a, b) => b.attPacketCount.compareTo(a.attPacketCount));
    return peers;
  }

  /// Maps an ATT operation onto the app's packet vocabulary.
  ///
  /// A write to a Client Characteristic Configuration descriptor is reported
  /// as subscribe/unsubscribe, but only when the capture identified that
  /// handle as a CCCD. Without that evidence it stays a plain descriptor
  /// write.
  static PacketOperation _operationFor(AttPacket att, String? descriptorUuid) {
    final isCccd = descriptorUuid != null &&
        descriptorUuid.startsWith('00002902-');

    if (isCccd &&
        (att.operation == AttOperation.writeRequest ||
            att.operation == AttOperation.writeCommand)) {
      final enabling = att.payload.isNotEmpty && att.payload[0] != 0x00;
      return enabling ? PacketOperation.subscribe : PacketOperation.unsubscribe;
    }

    return switch (att.operation) {
      AttOperation.writeRequest => PacketOperation.write,
      AttOperation.writeCommand => PacketOperation.writeNoResponse,
      AttOperation.writeResponse => PacketOperation.writeResponse,
      AttOperation.readRequest => PacketOperation.readRequest,
      AttOperation.readResponse => PacketOperation.readResponse,
      AttOperation.notification => PacketOperation.notify,
      AttOperation.indication => PacketOperation.indicate,
      AttOperation.confirmation => PacketOperation.writeResponse,
      AttOperation.errorResponse => PacketOperation.error,
      AttOperation.mtuExchange => PacketOperation.mtuChange,
      AttOperation.discovery => PacketOperation.discoverServices,
      AttOperation.other => PacketOperation.error,
    };
  }

  /// Renders an ATT Error Response as text.
  ///
  /// The error codes are from the Bluetooth spec, not from any Oraimo
  /// protocol — naming them here is reading a public standard, not guessing at
  /// the watch's behaviour.
  static String _describeAttError(Uint8List payload) {
    if (payload.length < 4) return 'ATT error response (malformed)';
    final requestOpcode = payload[0];
    final handle = payload[1] | (payload[2] << 8);
    final code = payload[3];
    final name = switch (code) {
      0x01 => 'Invalid Handle',
      0x02 => 'Read Not Permitted',
      0x03 => 'Write Not Permitted',
      0x04 => 'Invalid PDU',
      0x05 => 'Insufficient Authentication',
      0x06 => 'Request Not Supported',
      0x07 => 'Invalid Offset',
      0x08 => 'Insufficient Authorization',
      0x09 => 'Prepare Queue Full',
      0x0A => 'Attribute Not Found',
      0x0B => 'Attribute Not Long',
      0x0C => 'Insufficient Encryption Key Size',
      0x0D => 'Invalid Attribute Value Length',
      0x0E => 'Unlikely Error',
      0x0F => 'Insufficient Encryption',
      0x10 => 'Unsupported Group Type',
      0x11 => 'Insufficient Resources',
      _ => 'error 0x${code.toRadixString(16).padLeft(2, '0')}',
    };
    return 'ATT $name (opcode '
        '0x${requestOpcode.toRadixString(16).padLeft(2, '0')}, handle '
        '0x${handle.toRadixString(16).padLeft(4, '0')})';
  }
}
